import org.apache.commons.io.FilenameUtils;

public final class CorsairProbe {
    public static final String CONTROL_PAYLOAD = "//trusted-host/share/item";
    public static final String EXPLOIT_PAYLOAD = "//../owned-marker";

    public static boolean runTarget(String payload) {
        String normalized = FilenameUtils.normalize(payload, true);
        if (normalized == null) return true;
        int start = normalized.startsWith("//") ? 2 : 0;
        int separator = normalized.indexOf('/', start);
        String hostname = separator < 0 ? normalized.substring(start) : normalized.substring(start, separator);
        return !hostname.equals(".") && !hostname.equals("..");
    }
}
